<script nonce="<?= e(csp_nonce()) ?>">
const log=document.getElementById('chat-log'),form=document.getElementById('chat-form'),input=document.getElementById('chat-input'),send=document.getElementById('send-btn');
const csrf=<?= json_encode(csrf_token()) ?>;
function addMessage(text,who){const node=document.createElement('div');node.className='msg '+who;node.textContent=text;log.append(node);log.scrollTop=log.scrollHeight;return node;}
async function ask(text){if(send.disabled)return;send.disabled=true;addMessage(text,'user');const waiting=addMessage('Finding an answer…','bot');try{const response=await fetch('chat_api.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},credentials:'same-origin',body:JSON.stringify({message:text})});const result=await response.json();waiting.textContent=result.reply||'Please try again.';for(const source of result.sources||[]){if(!source||typeof source.url!=='string')continue;try{const url=new URL(source.url);if(url.protocol!=='https:')continue;const a=document.createElement('a');a.href=url.href;a.textContent=source.title||'Official source';a.target='_blank';a.rel='noopener noreferrer';waiting.append(document.createElement('br'),a);}catch(e){}}}catch(err){waiting.textContent='Sorry, the assistant could not be reached right now.';}finally{send.disabled=false;input.focus();log.scrollTop=log.scrollHeight;}}
form.addEventListener('submit',e=>{e.preventDefault();const msg=input.value.trim();if(!msg)return;input.value='';ask(msg);});
document.querySelectorAll('[data-prompt]').forEach(button=>button.addEventListener('click',()=>ask(button.dataset.prompt)));
</script>
